import os
import flask
from flask import Flask, render_template, request, jsonify
import random

app = Flask(__name__)

# Data structures and interfaces
def _c_optimizations_ignored() -> bool:
    """
    Return True if get "PURE_PYTHON" environ is not none and not 0, else return False
    """
    pure_python_env = os.getenv("PURE_PYTHON")
    return pure_python_env is not None and pure_python_env != "0"

# Initialize game state
game_state = {
    'score': 0,
    'board': [[0] * 4 for _ in range(4)],
    'game_over': False
}

# Helper function to add a new tile to the board
def add_new_tile(board):
    empty_tiles = [(i, j) for i in range(4) for j in range(4) if board[i][j] == 0]
    if empty_tiles:
        i, j = random.choice(empty_tiles)
        board[i][j] = 2 if flask.current_app.config['INITIAL_TILE_VALUE'] == 2 else 4
    return board

# Helper function to move the tiles in a specified direction
def move_tiles(direction):
    board = game_state['board']
    if direction == 'up':
        board = list(zip(*board))
    elif direction == 'down':
        board = list(zip(*board))[::-1]
    elif direction == 'left':
        board = [[num for num in row if num != 0] for row in board]
        for i in range(len(board)):
            for j in range(len(board[i]) - 1):
                if board[i][j] == board[i][j + 1]:
                    board[i][j] *= 2
                    board[i].pop(j + 1)
                    board[i].append(0)
    elif direction == 'right':
        board = [row[::-1] for row in board]
        board = [[num for num in row if num != 0] for row in board]
        for i in range(len(board)):
            for j in range(len(board[i]) - 1, 0, -1):
                if board[i][j] == board[i][j - 1]:
                    board[i][j] *= 2
                    board[i].pop(j - 1)
                    board[i].insert(0, 0)
    if direction == 'up' or direction == 'down':
        board = list(zip(*board))
    if direction == 'right' or direction == 'left':
        board = [row[::-1] for row in board]
    return board

# Route for the main game page
@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        direction = request.form.get('direction')
        game_state['board'] = move_tiles(direction)
        game_state['board'] = add_new_tile(game_state['board'])
        game_state['score'] += sum(sum(row) for row in game_state['board'])
        game_state['game_over'] = all(all(row) for row in game_state['board'])
        return jsonify(game_state)
    return render_template('index.html', game_state=game_state)

# Route for restarting the game
@app.route('/restart', methods=['POST'])
def restart():
    game_state.update(score=0, board=[[0] * 4 for _ in range(4)], game_over=False)
    return jsonify(game_state)

if __name__ == '__main__':
    app.config.update(INITIAL_TILE_VALUE=2)
    app.run(debug=True)

