from pathlib import PosixPath

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file at {archive_path} does not exist.")

    if archive_path.endswith('.tar'):
        extract_tar_archive(archive_path, tmp_path)
    elif archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        extract_tar_archive(archive_path, tmp_path, 'gz')
    elif archive_path.endswith('.zip'):
        extract_zip_archive(archive_path, tmp_path)
    else:
        raise ValueError("Unsupported archive format. Only .tar, .tar.gz, .tgz, and .zip formats are supported.")

    # Assuming the extraction process places the repository in a directory named after the archive file (without extension)
    repo_dir = os.path.splitext(os.path.basename(archive_path))[0]
    repo_url = os.path.join(tmp_path, repo_dir)
    return repo_url

def extract_tar_archive(archive_path: str, tmp_path: Union[PosixPath, str], compression: str = 'bz2'):
    """
    Extract a tar archive.
    @param archive_path: Path to the tar archive.
    @param tmp_path: Path to the directory where the archive will be extracted.
    @param compression: Compression type ('bz2', 'gz').
    """
    with tarfile.open(archive_path, f"r:{compression}") as tar:
        tar.extractall(path=tmp_path)

def extract_zip_archive(archive_path: str, tmp_path: Union[PosixPath, str]):
    """
    Extract a zip archive.
    @param archive_path: Path to the zip archive.
    @param tmp_path: Path to the directory where the archive will be extracted.
    """
    with zipfile.ZipFile(archive_path, 'r') as zip_ref:
        zip_ref.extractall(tmp_path)

