from typing import List
import datetime
import re
from typing import Optional

def parse_frequency(frequency: Optional[str]) -> Optional[datetime.timedelta]:
    if frequency is None or frequency == 'always':
        return None

    pattern = re.compile(r'^(\d+)\s*(seconds?|minutes?|hours?|days?|weeks?)$')
    match = pattern.match(frequency)

    if not match:
        raise ValueError("Invalid frequency string")

    value = int(match.group(1))
    unit = match.group(2)

    if unit == 'seconds':
        return datetime.timedelta(seconds=value)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=value)
    elif unit == 'hours':
        return datetime.timedelta(hours=value)
    elif unit == 'days':
        return datetime.timedelta(days=value)
    elif unit == 'weeks':
        return datetime.timedelta(weeks=value)
    else:
        raise ValueError("Invalid time unit")

