from typing import List, Dict

def from_raw_values(values: List[str]) -> Dict[str, List[str]]:
    """
    Create a dictionary of bookmarks where keys are category names and values are lists of bookmark strings.
    """
    bookmarks = {}
    for value in values:
        parts = value.split(maxsplit=1)
        if len(parts) == 2:
            category, bookmark = parts
            if category not in bookmarks:
                bookmarks[category] = []
            bookmarks[category].append(bookmark)
    return bookmarks
